SELECT u.id, u.email, u.nickname
FROM users u
WHERE u.id::text = #{identity} OR u.email = #{identity}

INSERT INTO invoice (
    user_id, doc_type, doc_no, source_quote_id, title, content,
    supply_amount, vat_amount, total_amount
)
VALUES (
    #{userId}, #{type}, #{number}, #{sourceId,jdbcType=BIGINT}, #{title}, CAST(#{content} AS jsonb),
    #{amounts.supply}, #{amounts.vat}, #{amounts.total}
)
RETURNING id

SELECT EXISTS (
    SELECT 1
    FROM photo p
    WHERE p.id = CAST(#{photoId} AS uuid) AND p.user_id = #{userId}
)
